mkdir -p <world>/repo/.workit-scratch && cd <world>/repo/.workit-scratch && cat > probe.mjs <<'EOF'
import fs from 'node:fs';
const src = fs.readFileSync(process.argv[2], 'utf8');
const js = src.replace('(a: number, b: number): number', '(a, b)');
fs.writeFileSync(new URL('./mul.mjs', import.meta.url), js);
const { mul } = await import('./mul.mjs');
const cases = [[2,3,6],[0,5,0],[-4,3,-12],[1.5,2,3]];
for (const [a,b,e] of cases) if (mul(a,b)!==e) { console.log('FAIL',a,b); process.exit(1); }
console.log('ok', typeof mul, mul.length);
EOF
echo done

S=<world>/repo/.workit-scratch; mkdir -p $S; cat > $S/probe.mjs <<'EOF'
import { readFileSync, writeFileSync } from "node:fs";
import { stripTypeScriptTypes } from "node:module";
const src = readFileSync(process.argv[2], "utf8");
const js = stripTypeScriptTypes(src);
const out = process.argv[3];
writeFileSync(out, js);
const m = await import(out);
const cases = [[1,2,3],[-1,1,0],[0.5,0.25,0.75],[0,0,0]];
let ok = typeof m.add === "function" && m.add.length === 2;
for (const [a,b,e] of cases) { const r = m.add(a,b); console.log(a,b,r); if (r!==e) ok=false; }
console.log(ok ? "PASS" : "FAIL"); process.exit(ok?0:1);
EOF
cd $S && node probe.mjs <world>/state/worktrees/repo/add/src/add.ts $S/add.out.mjs; echo exit=$?

